theorem MIPRE.LIDT.LowIndDegPoly.eval_coef_of_eq_off (g : LowIndDegPoly (F := F) (m := n) (d := d))
    (T : Finset (Fin n)) (t : Fin n → Fin (d + 1)) {u u' : Point F n}
    (h : ∀ k ∉ T, u k = u' k) : (g.coef T t).eval u = (g.coef T t).eval u' := by sorry

theorem MIPRE.QLD.MS.pvBit_rep (c : Fin layout.r) {a : Fin layout.s → ZMod 2}
    (ha : (∑ k ∈ layout.V c, a k) = game.b c) (j : Fin 3) :
    pvBit c (rep c (Sum.inl a)) j = a (cell c j) := by sorry

theorem MIPRE.snorm_aOp_mul_one_sub_le (Φ : RA × RB → ℂ) {T A : Matrix RA RA ℂ} {B : Matrix RB RB ℂ}
    (hT : Tᴴ = T) (hTi : T * T = T) (hB : Bᴴ = B) (hBi : B * B = B) :
    snorm Φ ((aOp (T * (1 - A)) : Matrix (RA × RB) _ ℂ)) ≤ xNorm Φ T B + xNorm Φ A B := by sorry

theorem MIPRE.QLD.pAB_ne_linAB (hd : 1 ≤ d) {g : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    {e₀ : Fin (4 * m) → Fin (d + 1)}
    (hpat : ¬ (((e₀ (aIdx m) : ℕ) = 1 ∧ (e₀ (bIdx m) : ℕ) = 0)
      ∨ ((e₀ (aIdx m) : ℕ) = 0 ∧ (e₀ (bIdx m) : ℕ) = 1)))
    {u₀ : Point F (4 * m)} (hu : (g.coef abSet (patAB (e₀ (aIdx m)) (e₀ (bIdx m)))).eval u₀ ≠ 0)
    (a b : F) : pAB g u₀ ≠ linAB hd a b := by sorry

theorem MIPRE.QLD.sum_sub_le_of_eq_on {A B S : G → ℝ} {ML : Finset G}
    (hon : ∀ g ∈ ML, A g = B g) (hA : ∀ g, |A g| ≤ S g) (hB : ∀ g, |B g| ≤ S g) :
    |∑ g, A g - ∑ g, B g| ≤ 2 * ∑ g ∈ univ \ ML, S g := by sorry

theorem MIPRE.conjTranspose_conv_mul_conv (Z : C → Matrix dB dB ℂ) {T : C → Matrix anc' anc' ℂ}
    (hT : IsPVM T) (c : C) :
    (conv (dB := dB) Z T c)ᴴ * conv Z T c = conv (fun a => (Z a)ᴴ * Z a) T c := by sorry

theorem MIPRE.sum_normSq_stateVecB_conv_eq (ψ : dA × dB → ℂ) {e : anc × anc' → ℂ}
    (he : star e ⬝ᵥ e = 1) (Z : C → Matrix dB dB ℂ) {T : C → Matrix anc' anc' ℂ} (hT : IsPVM T) :
    ∑ c, ‖stateVecB (expVec ψ e) (conv Z T c)‖ ^ 2 = ∑ a, ‖stateVecB ψ (Z a)‖ ^ 2 := by sorry

theorem MIPRE.QLD.pAB_eq_linAB_of_isLinAB (hd : 1 ≤ d) {g : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    (hg : IsLinAB g) (u₀ : Point F (4 * m)) :
    pAB g u₀ = linAB hd ((gA hd g).eval u₀) ((gB hd g).eval u₀) := by sorry

theorem MIPRE.QLD.isGood_of (hd : 1 ≤ d) {g : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    (hlin : IsLinAB g) (hA : ¬ (gA hd g).DepOutside xSet) (hB : ¬ (gB hd g).DepOutside zSet) :
    IsGood g := by sorry

theorem MIPRE.QLD.sum_uniform_bornProb_readOn_le {T : Finset (Fin (4 * m))}
    {Op : Point F (4 * m) → F → Matrix RB RB ℂ} (hOp : ∀ u u', Op (mixOn T u u') = Op u')
    (hpvm : ∀ u, IsPVM (Op u)) {H : LowIndDegPoly (F := F) (m := 4 * m) (d := d)}
    (hH : H.DepOutside T) (Φ : RA × RB → ℂ) {S : Matrix RA RA ℂ} (hS : S.PosSemidef) :
    ∑ u, uniform (Point F (4 * m)) u * bornProb Φ S (Op u (H.eval u))
      ≤ 8 * m * d / Fintype.card F * bornProb Φ S 1 := by sorry

theorem MIPRE.QLD.sum_snorm_sq_sub_eq_two_sub {v : N → ℂ} (hv : ‖evec v‖ = 1) {A T : Λ → Matrix N N ℂ}
    (hA : IsPVM A) (hT : IsPVM T) :
    ∑ h, snorm v (A h - T h) ^ 2 = 2 - 2 * ∑ h, qform v (A h * T h) := by sorry

theorem MIPRE.sum_xSqNorm_le_of_two_step {κ : Type*} [Fintype κ] {ψ : dA × dB → ℂ}
    (Q Q' : κ → Matrix dA dA ℂ) (R : κ → Matrix dB dB ℂ) {a b : ℝ}
    (h1 : ∑ o, stateSqNorm ψ (Q o - Q' o) ≤ a) (h2 : ∑ o, xSqNorm ψ (Q' o) (R o) ≤ b) :
    ∑ o, xSqNorm ψ (Q o) (R o) ≤ 2 * a + 2 * b := by sorry

