theorem MIPRE.Introspection.one_le_soundness_power_of_threshold_le (r n : ℕ) {edges t : ℝ}
    (hE : 0 ≤ edges) (ht : adaptiveSmallThreshold r edges n ≤ t) :
    1 ≤ adaptiveSoundnessCoefficient r edges n * iteratedRoot (3 * n) t := by sorry

theorem MIPRE.Introspection.CLChecks.stageFactor_subset_residual {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (k : ℕ) (y : ι → F) :
    P.factorOfPrefix k y ⊆ T \ prefixRegister P k y := by sorry

theorem MIPRE.Introspection.CLChecks.proj_prefixRegister {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (k : ℕ) (y : ι → F) :
    CL.proj (prefixRegister P k y) y = P.outputPrefix k y := by sorry

theorem MIPRE.Introspection.AuxiliaryDual.proj_decodeDual {P : CL.CLFun F (ι) ℓ} {T : Finset (ι)}
    (hP : P.SupportedOn T) (y x : ι → F) {k : ℕ} (hk : k < ℓ) :
    CL.proj (P.factorOfPrefix k y) (decodeDual P y x) = stageDual P k y x := by sorry

theorem MIPRE.Introspection.AuxiliaryQuotient.hidingNext_of_legacy {P : CL.CLFun F (ι) ℓ} {T : Finset (ι)}
    (hP : P.SupportedOn T) (k : ℕ) (u v : RegisterHideAnswer F ι)
    (h : CLChecks.hidingNext P k u v) : hidingNext P k u v := by sorry

theorem MIPRE.Introspection.errorProfile_scale_input {a b c x ε : ℝ}
    (ha : 0 ≤ a) (hc : 0 ≤ c) (hx : 0 ≤ x) (hε : 0 ≤ ε) :
    errorProfile a b x (c * ε) ≤ max 1 (c ^ b) * errorProfile a b x ε := by sorry

theorem MIPRE.Introspection.CLChecks.outputPrefix_outputPrefix {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (y : ι → F) {k m : ℕ} (hkm : k ≤ m) :
    P.outputPrefix k (P.outputPrefix m y) = P.outputPrefix k y := by sorry

theorem MIPRE.Introspection.CLChecks.dualReadout_congr {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (k : ℕ) (y : ι → F) {x t : ι → F}
    (h : ∀ i ∈ T, x i = t i) : dualReadout P k y x = dualReadout P k y t := by sorry

theorem MIPRE.Introspection.CLChecks.proj_outputPrefix_cons {S T : Finset ι} {L : CL.RegLinear F S}
    {next : (ι → F) → CL.CLFun F ι ℓ}
    (hP : (CL.CLFun.cons S L next).SupportedOn T) (k : ℕ) (y : ι → F) :
    CL.proj S ((CL.CLFun.cons S L next).outputPrefix (k + 1) y) = CL.proj S y ∧
    CL.proj Sᶜ ((CL.CLFun.cons S L next).outputPrefix (k + 1) y) =
      (next (CL.proj S y)).outputPrefix k (CL.proj Sᶜ y) := by sorry

theorem MIPRE.Introspection.HonestMagicSquare.grid_isObservable {A B : Matrix I I ℂ}
    (hA : IsObservable A) (hB : IsObservable B) (hAB : A * B = -(B * A))
    (j : Fin 9) : IsObservable (grid A B j) := by sorry

theorem MIPRE.Introspection.HonestMagicSquare.cells_commute {A B : Matrix I I ℂ}
    (hAB : A * B = -(B * A)) (c : Fin layout.r) (s t : Fin 3) :
    Commute (grid A B (cellIndex c s)) (grid A B (cellIndex c t)) := by sorry

theorem MIPRE.Introspection.HonestMagicSquare.constraintOp_isPVM {A B : Matrix I I ℂ}
    (hA : IsObservable A) (hB : IsObservable B) (hAB : A * B = -(B * A))
    (c : Fin layout.r) : IsPVM (constraintOp A B c) := by sorry

theorem MIPRE.LowDegree.BinaryLinear.mulBits_matrixBits {m n r : ℕ}
    (A : Matrix (Fin m) (Fin r) (ZMod 2)) (B : Matrix (Fin r) (Fin n) (ZMod 2)) :
    mulBits n (matrixBits A) (matrixBits B) = matrixBits (A * B) := by sorry

theorem MIPRE.condFail_le_one_sub_sum_bornProb_diag {G : Game X Y A A} {MA : X → POVM A dA}
    {MB : Y → POVM A dB}
    (hD : ∀ a, ((MA x).mats a).val ≠ 0 → ((MB y).mats a).val ≠ 0 → G.D x y a a = true) :
    condFail G ψ MA MB x y
      ≤ 1 - ∑ a, bornProb ψ (((MA x).mats a).val) (((MB y).mats a).val) := by sorry

theorem MIPRE.sum_bornProb_le_fibSum (ψ : dA × dB → ℂ) {X : α → Matrix dA dA ℂ}
    {X' : α → Matrix dB dB ℂ} (hX : IsPVM X) (hX' : IsPVM X') (e : α → β) :
    ∑ a, bornProb ψ (X a) (X' a) ≤ ∑ b, bornProb ψ (fibSum X e b) (fibSum X' e b) := by sorry

theorem MIPRE.sum_snorm_sq_comm_coarse_le {ψ : dA × dB → ℂ} {A : R1 × R2 → Matrix dA dA ℂ}
    {Gf : R2 → Matrix dB dB ℂ} (hA : IsPVM A) (hR : IsPVM R) (hGf : IsPVM Gf) {δ₁ δ₂ : ℝ}
    (h1 : ∑ a : R1, xSqNorm ψ (∑ b : R2, A (a, b)) (R a) ≤ δ₁)
    (h2 : ∑ b : R2, xSqNorm ψ (∑ a : R1, A (a, b)) (Gf b) ≤ δ₂) :
    ∑ a : R1, ∑ b : R2, snorm ψ (bOp (R a * Gf b - Gf b * R a) : Matrix (dA × dB) _ ℂ) ^ 2
      ≤ 16 * (δ₁ + δ₂) := by sorry

theorem MIPRE.TensorProductStrategy.value_eq_povmValue {G : Game X Y A B}
    (S : TensorProductStrategy G) :
    S.value = povmValue G S.ψ (fun x => S.PA.toPOVM x) (fun y => S.PB.toPOVM y) := by sorry

theorem MIPRE.one_sub_sum_bornProb_eq {A : Type*} [Fintype A] [DecidableEq A] {ψ : dA × dB → ℂ}
    (hψ : ‖evec ψ‖ = 1) {X : A → Matrix dA dA ℂ} {X' : A → Matrix dB dB ℂ}
    (hX : IsPVM X) (hX' : IsPVM X') :
    1 - ∑ a, bornProb ψ (X a) (X' a) = (∑ a, xSqNorm ψ (X a) (X' a)) / 2 := by sorry
